36	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
37	export async function startEngineWith(
38	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
39	): Promise<{url: string; hal: HalServer}> {
40	  const hal = createServer({
41	    app: (() => undefined) as unknown as Express,
42	    wsAuth: async () => ({id: 'u1'}),
43	    orchestrator: answeringOrchestrator,
44	    ...options,
45	  });
46	  await hal.start(0);
47	  servers.push(hal);
48	  const {port} = hal.server.address() as AddressInfo;
49	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
50	}
