import {WebSocket} from 'ws';
import {setLogger} from '../shared/logger.js';

// Test that verifies WebSocket cleanup doesn't trigger async logging after test ends

describe('WebSocket cleanup', () => {
  const loggedEvents: Array<{category: string; message: string}> = [];

  beforeEach(() => {
    loggedEvents.length = 0;
    const record = (level: string) => (category: string, message: string) => {
      loggedEvents.push({category, message});
    };
    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
  });

  afterEach(() => {
    setLogger();
  });

  it('closes WebSocket clients without leaving pending disconnect logging', async () => {
    // Simulate what happens in the acceptance test: creating multiple WebSocket clients
    // and ensuring they don't leave async logging pending after test ends

    // This test just verifies that calling close() on a WebSocket doesn't leave
    // operations pending that would cause "Cannot log after tests are done" errors
    const client = new WebSocket('ws://localhost:9999'); // Invalid address won't connect

    // Ensure close handlers are properly awaited
    await new Promise<void>(resolve => {
      client.on('close', () => resolve());
      client.on('error', () => resolve()); // Handle connection errors
      client.close();
    });

    expect(client.readyState).toBe(WebSocket.CLOSED);
  });
});

